import Cocoa

// Get accessibility element for the simulator window
func getAccessibilityElement(app: NSAccessibility.Attribute) -> Any? {
    let runningApps = NSWorkspace.shared.runningApplications
    guard let simulatorApp = runningApps.first(where: { $0.bundleIdentifier == "com.apple.CoreSimulator.CoreSimulatorService" || $0.localizedName.contains("Simulator") }) else {
        print("Simulator not found")
        return nil
    }

    guard let windows = simulatorApp.accessibilityElement() else {
        print("Could not get simulator accessibility element")
        return nil
    }

    return windows
}

// Function to find and tap the first post
func tapFirstPost() {
    let timeout = 5.0
    let start = Date()

    while Date().timeIntervalSince(start) < timeout {
        let runningApps = NSWorkspace.shared.runningApplications

        // Find the Simulator app
        if let simulatorApp = runningApps.first(where: { $0.localizedName.contains("Simulator") }) {
            if let appElement = simulatorApp.accessibilityElement() as? NSAccessibilityElement {
                // Try to find the first post element
                // Posts in Bluesky typically have a text element with the author name
                if let windows = appElement.accessibilityChildren() {
                    for window in windows {
                        if let windowElement = window as? NSAccessibilityElement {
                            // Search for post-like elements
                            searchAndTapPost(element: windowElement)
                            return
                        }
                    }
                }
            }
        }

        usleep(500000) // Wait 500ms before retrying
    }

    print("Could not find first post within timeout")
}

func searchAndTapPost(element: NSAccessibilityElement) {
    // Look for elements that contain post text
    if let role = element.accessibilityRole() as? String {
        // Check if this could be a post
        if let label = element.accessibilityLabel() as? String {
            if label.contains("whiskers") || label.contains("Mochi") {
                print("Found post element: \(label)")
                // Try to activate/tap it
                if element.accessibilityPerform(.press) {
                    print("Successfully tapped post!")
                    return
                }
            }
        }
    }

    // Recursively search children
    if let children = element.accessibilityChildren() {
        for child in children {
            if let childElement = child as? NSAccessibilityElement {
                searchAndTapPost(element: childElement)
            }
        }
    }
}

