#!/usr/bin/swift
import Cocoa

// Function to find and tap the first post
func tapFirstPost() {
    let timeout = 5.0
    let start = Date()

    while Date().timeIntervalSince(start) < timeout {
        let runningApps = NSWorkspace.shared.runningApplications

        // Find the Simulator app
        for app in runningApps {
            if let bundleID = app.bundleIdentifier, bundleID.contains("Simulator") || app.localizedName?.contains("Simulator") ?? false {
                if let appElement = app.accessibilityElement() as? NSAccessibilityElement {
                    // Search for post-like elements
                    if searchAndTapPost(element: appElement) {
                        return
                    }
                }
            }
        }

        usleep(500000) // Wait 500ms before retrying
    }

    print("Could not find first post within timeout")
}

func searchAndTapPost(element: NSAccessibilityElement) -> Bool {
    // Look for elements that contain post text
    if let label = element.accessibilityLabel() as? String {
        if label.contains("whiskers") || label.contains("Mochi") {
            print("Found post element: \(label)")
            // Try to activate/tap it
            element.accessibilityPerform(NSAccessibilityCustomAction(name: "AXPress", handler: { true }))

            // Alternative: try sending a click event
            if let frame = element.accessibilityFrame(), !frame.isEmpty {
                let clickPoint = CGPoint(x: frame.midX, y: frame.midY)
                let event = CGEvent(mouseEventSource: nil, mouseType: .leftMouseDown, mouseCursorPosition: clickPoint, timestamp: 0)
                event?.post(tap: .cghidEventTap)

                let eventUp = CGEvent(mouseEventSource: nil, mouseType: .leftMouseUp, mouseCursorPosition: clickPoint, timestamp: 0)
                eventUp?.post(tap: .cghidEventTap)

                print("Successfully tapped post!")
                return true
            }
        }
    }

    // Recursively search children
    if let children = element.accessibilityChildren() as? [NSAccessibilityElement] {
        for child in children {
            if searchAndTapPost(element: child) {
                return true
            }
        }
    }

    return false
}

// Main
tapFirstPost()

