#!/usr/bin/swift
import Cocoa

func tapOpenButton() {
    guard let frontApp = NSWorkspace.shared.frontmostApplication else {
        print("No frontmost app")
        return
    }

    print("Frontmost app: \(frontApp.localizedName ?? "unknown")")

    guard let appAXRef = AXUIElementCreateApplication(frontApp.processIdentifier) else {
        print("Failed to get app AXRef")
        return
    }

    // Try to find the "Open" button in the dialog
    findAndTapButton(element: appAXRef, buttonTitle: "Open")
}

func findAndTapButton(element: AXUIElement, buttonTitle: String) {
    var result: AnyObject?

    // Get the window
    let err = AXUIElementCopyAttributeValue(element, kAXWindowsAttribute as CFString, &result)

    guard err == .success, let windows = result as? [AXUIElement] else {
        print("Could not get windows: \(err)")
        return
    }

    print("Found \(windows.count) windows")

    for window in windows {
        searchWindow(window, for: buttonTitle)
    }
}

func searchWindow(_ element: AXUIElement, for buttonTitle: String) {
    var result: AnyObject?

    // Check current element
    let titleErr = AXUIElementCopyAttributeValue(element, kAXTitleAttribute as CFString, &result)
    if titleErr == .success, let title = result as? String {
        print("Found element: \(title)")
    }

    // Get children
    let childrenErr = AXUIElementCopyAttributeValue(element, kAXChildrenAttribute as CFString, &result)
    guard childrenErr == .success, let children = result as? [AXUIElement] else {
        return
    }

    print("Found \(children.count) children")

    for child in children {
        // Check if this is a button with the title we're looking for
        var buttonResult: AnyObject?
        let buttonRoleErr = AXUIElementCopyAttributeValue(child, kAXRoleAttribute as CFString, &buttonResult)

        if buttonRoleErr == .success, let role = buttonResult as? String, role == "AXButton" {
            var titleResult: AnyObject?
            let titleErr = AXUIElementCopyAttributeValue(child, kAXTitleAttribute as CFString, &titleResult)

            if titleErr == .success, let title = titleResult as? String, title == buttonTitle {
                print("Found button: \(title), tapping...")

                // Tap the button
                let pressErr = AXUIElementPerformAction(child, kAXPressAction as CFString)
                print("Press result: \(pressErr)")
                return
            }
        }

        // Recursively search children
        searchWindow(child, for: buttonTitle)
    }
}

tapOpenButton()

