#!/usr/bin/swift
import Cocoa

func dumpAccessibility() {
    guard let frontApp = NSWorkspace.shared.frontmostApplication else {
        print("No frontmost app")
        return
    }

    print("Frontmost app: \(frontApp.localizedName ?? "unknown")")

    let appAXRef = AXUIElementCreateApplication(frontApp.processIdentifier)
    var result: AnyObject?

    let err = AXUIElementCopyAttributeValue(appAXRef, kAXWindowsAttribute as CFString, &result)
    guard err == .success, let windows = result as? [AXUIElement] else {
        print("Could not get windows: \(err)")
        return
    }

    print("Found \(windows.count) windows\n")

    for (idx, window) in windows.enumerated() {
        print("=== Window \(idx) ===")
        dumpElement(window, indent: 0)
    }
}

func dumpElement(_ element: AXUIElement, indent: Int, maxDepth: Int = 3) {
    guard indent < maxDepth else { return }

    let indentStr = String(repeating: "  ", count: indent)
    var result: AnyObject?

    // Get role
    let roleErr = AXUIElementCopyAttributeValue(element, kAXRoleAttribute as CFString, &result)
    let role = (roleErr == .success) ? (result as? String ?? "unknown") : "no-role"

    // Get title
    var title = ""
    let titleErr = AXUIElementCopyAttributeValue(element, kAXTitleAttribute as CFString, &result)
    if titleErr == .success, let t = result as? String {
        title = " Title: \(t)"
    }

    print("\(indentStr)[\(role)]\(title)")

    // Get children
    let childrenErr = AXUIElementCopyAttributeValue(element, kAXChildrenAttribute as CFString, &result)
    if childrenErr == .success, let children = result as? [AXUIElement] {
        for child in children {
            dumpElement(child, indent: indent + 1, maxDepth: maxDepth)
        }
    }
}

dumpAccessibility()

